<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#222;font-size:12px}h1{color:#176b5b}.box{border:1px solid #ddd;padding:14px;margin:12px 0}.label{color:#666;font-size:10px}p{line-height:1.6}.firma{margin-top:55px;border-top:1px solid #222;width:280px;padding-top:6px}</style></head><body><h1>Contrato de membresía FitControl</h1><div class="box"><div class="label">NÚMERO</div><strong>{{ $contrato->numero_contrato }}</strong><p><strong>Cliente:</strong> {{ $contrato->cliente_nombre }}<br><strong>Plan:</strong> {{ $contrato->plan_nombre }}<br><strong>Precio:</strong> {{ number_format($contrato->precio,2) }} {{ $contrato->moneda }}<br><strong>Vigencia:</strong> {{ $contrato->fecha_inicio }} al {{ $contrato->fecha_fin }}</p></div><h3>Condiciones</h3><p>{{ $contrato->condiciones }}</p><h3>Política de congelación</h3><p>{{ $contrato->politica_congelacion }}</p><h3>Política de cancelación</h3><p>{{ $contrato->politica_cancelacion }}</p><div class="firma">Aceptado por: {{ $contrato->firma_nombre }}<br>{{ $contrato->aceptado_at }}</div></body></html>
